#!/bin/sh
# Writes AKitCore/Sources/AKitRender/FlowTemplateSources.swift from Resources/flows/*.ts.
# The Pi runner templates live in the code, not in a bundle: SwiftPM's .embedInCode fails in the
# universal release build (xcodebuild), and a bundle could go missing next to the `akit` binary.
# FlowApplyTests keeps the generated file equal to Resources/flows (make test fails on drift).
set -eu
cd "$(dirname "$0")/.."
src=AKitCore/Sources/AKitRender/Resources/flows
out=AKitCore/Sources/AKitRender/FlowTemplateSources.swift
tmp="$out.tmp"
{
  echo "// Generated by tools/gen-flow-templates.sh from Resources/flows/*.ts. Do not edit by hand."
  echo "enum FlowTemplateSources {"
  for f in "$src"/*.ts; do
    name=$(basename "$f" .ts | tr '-' '_')
    if grep -q '"""####' "$f"; then echo "$f holds the raw-string end marker" >&2; exit 1; fi
    printf '    static let %s_ts = ####"""\n' "$name"
    cat "$f"
    # Swift drops the newline right before the closing marker: add one so the text keeps its
    # own final newline (a file without one gets a newline that Swift then drops).
    echo
    echo '"""####'
  done
  echo "}"
} > "$tmp"
mv "$tmp" "$out"
